get, \"_blank\");\n    return true;\n}","isdbcustom":true,"modelCode":"WOM_1.0.0_outputMaterial_OutMateDetail","downloadXls":"/msService/WOM/outputMaterial/outMateDetail/downloadXls","selectFirstRow":false,"renderOver":"//生产报工明细列表\nsetTimeout(function () {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_outputMaterial_outputDetailList_outMateDetail_sdg\").getDatagridData();\n    let materialId = [];\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].prodctId != null && data[i].prodctId.id != null) {\n            materialId.push({ \"materialId\": data[i].prodctId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.code = 200) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_outputMaterial_outputDetailList_outMateDetail_sdg\")\n                        .setDatagridCellAttr(i, \"prodctId.code\", { style: { color: \"#B30303\" } });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_outputMaterial_outputDetailList_outMateDetail_sdg\")\n                        .setDatagridCellAttr(i, \"prodctId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    }\n    );\n}, 1000);","buttons":[{"id":"viewDetail","showname":"查看报工单","name":"查看报工单","namekey":"查看报工单","i18nKey":"查看报工单","buttonstyle":"view","operatetype":"CUSTOM","operateType":"CUSTOM","is