ts = path.split(\".\");\n        for (var index = 0; index < parts.length; index += 1) {\n            if (value === null || value === undefined) { return null; }\n            value = value[parts[index]];\n        }\n        if (value && typeof value === \"object\" && value.id !== undefined) {\n            return value.id;\n        }\n        return value;\n    }\n    var recordId = valueAtPath(row, \"headId.id\");\n    if (!recordId) {\n        ReactAPI.showMessage(\"w\", \"请选择一条生产报工明细\");\n        return false;\n    }\n    var target = \"/msService/WOM/outputMaterial/outputMaterial/outputView\"\n        + \"?viewCode=WOM_1.0.0_outputMaterial_outputDetailList\"\n        + \"&entityCode=WOM_1.0.0_outputMaterial\"\n        + \"&iscrosscompany=false\"\n        + \"&openType=frame\"\n        + \"&iscallback=false\"\n        + \"&id=\" + encodeURIComponent(recordId);\n    window.open(target, \"_blank\");\n    return true;\n}","layoutmethod":"container","isExportExcel":true,"hasFastQuery":true,"isTreeView":false,"fields":[{"assPropertyName":"id","ass":{"tar":"WOM_1.0.0_outputMaterial_OutputMaterial_id","org":"WOM_1.0.0_outputMaterial_OutMateDetail_headId"},"precisionHasChanged":true,"code":"WOM_1.0.0_outputMaterial_outputDetailList_LISTPT_OTHER_WOM_1.0.0_outputMaterial_OutMateDetail_headId_WOM_1.0.0_outputMaterial_OutputMaterial_tableNo","isTotal":false,"isOrderBy":false,"seniorSystemcode":false,"displayName":"WOM.propertyshowName.randon1575883460749.flag","showFormatHasChanged":false,"isCount":false,"linkView":{"code":"WOM_1.0.0_outputMaterial_outputView","pc":"__pc__=V09NXzEuMC4wX291dHB1dE1hdGVyaWFsX291dHB1dExpc3Rfc2VsZnw_","iscrosscompany":"false","name":"outputView","title":"WOM.viewtitle.randon1575884168869","url":"/msService/WOM/outputMaterial/outputMaterial/outputView","openType":"frame"},"ecEnv":"product","propertyCode":"WOM_1.0.0_outputMaterial_OutMateDetail_headId||WOM_1.0.0_outputMaterial_OutputMaterial_tableNo","regionType":"LISTPT","layRec":"WOM_OUTPUT_MATERI