"regionType":"EDIT","rowspan":1,"cellCode":"cell_1589792496110_8504","type":"layoutCell"},{"colspan":1,"regionType":"EDIT","rowspan":1,"cellCode":"cell_1589792496111_6649","type":"layoutCell"},{"colspan":1,"regionType":"EDIT","rowspan":1,"cellCode":"cell_1589792496111_2307","type":"layoutCell"},{"colspan":1,"regionType":"EDIT","rowspan":1,"cellCode":"cell_1589792496112_1680","type":"layoutCell"}],"regionType":"EDIT","colwidth":"13,20,13,20,13,20","cssstyle":"display:none","customSection":null,"colNum":6,"name":null,"sectionCode":"section_1589792496107_4204","refcol":"<tr style=''border:none;height:0px; ''><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td></tr>","type":"layoutSection"}],"isrightbottomfixed":false,"layoutContent":"section","type":"layout","ranksType":"panel","isShow":true,"isreadonlyBak":0,"parlayoutname":"tabs-3","ratio_h":15,"layoutmethod":"container","ptRealTimeLoad":0,"isreadonly":0,"layno":3,"layoutname":"column-10","islefttopfixed":false,"nums":1},{"isborder":0,"tabViewIndex":0,"components":[{"isborder":0,"components":[{"canInsertRow":false,"isSuperTable":false,"iscontrol":false,"nullable":false,"isTransverseShow":false,"isOfficeHandSign":false,"isRevision":false,"isFirstLoad":false,"type":"layoutDatagrid","isEditable":false,"readonly":0,"ptPageInit_es5":"//$(\"#btn-otherActive\").hide();\n// 样式修改不可使用JQuery,需要使用平台提供的方法\nvar sdg = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988483'');\n// 开始样式\nsdg.setBtnImg(''btn-startProcess'', ''sup-btn-own-qiyong'');\n// 停止样式\nsdg.setBtnImg(''btn-endProcess'', ''sup-btn-own-ty'');\n\n// 工序列表\nvar processDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988483'');\n// 指令单\nvar task = ReactAPI.getFormData();\n// 指令单执行状态\nvar taskRunState = task.taskRunState.id;\n// 设置点击事件\nprocessDataGrid.setClickEvt(function (event, process) {\n    var processRunState = process.processRunState.id;\n    // 开始工序按钮，情况：指令单在执行中，且工序在待执行状态\n    setBtnStyle(''btn-startProcess'', taskRunState === ''WOM_runState/runing'' && processRunState === ''WOM_runState/waitForRun'');\n\n    // 结束工序按钮, 情况：指令单在执行中，且工序在进行中状态\n    setBtnStyle(''btn-endProcess'', taskRunState === ''WOM_runState/runing'' && processRunState === ''WOM_runState/runing'');\n\n    // 设置工作单元按钮，情况：指令单在执行中，且工序在进行中状态\n    setBtnStyle(''btn-setUnit'', taskRunState === ''WOM_runState/runing'' && processRunState === ''WOM_runState/runing'');\n\n    // 机动执行按钮，情况：指令单在非待执行，且工序在非待执行中\n    setBtnStyle(''btn-otherActive'', taskRunState !== ''WOM_runState/waitForRun'' && processRunState !== ''WOM_runState/waitForRun'');\n\n    var activeDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988507'');\n    // 根据工单工序获取工单活动\n    activeDataGrid.refreshDataByRequst({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/taskActive/queryByProcess?processId=\" + process.id + \"&showBatch=false\",\n        param: {}\n    });\n    //判断物料属性是否为危化品\n    setTimeout(function () {\n        var data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskViewdg1576028988507\").getDatagridData();\n        console.log(data);\n\n        var _loop = function _loop(i) {\n            if (data[i].materialId != null) {\n                //如果物料编码字段不为空，则发送请求\n                ReactAPI.request({\n                    type: \"get\",\n                    url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttribute?materialCode=\" + data[i].materialId.id,\n                    contentType: \"application/json;charset=UTF-8\"\n                }, function (res) {\n                    if (res.code == 200) {\n                        if (res.data.materialAttr == true) {\n                            //如果是危化品则为红色\n                            ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskViewdg1576028988507\").setDatagridCellAttr(data[i].rowIndex, \"materialId.code\", { style: { color: \"#B30303\" } });\n                        } else {\n                            ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskViewdg1576028988507\").setDatagridCellAttr(data[i].rowIndex.rowIndex, \"materialId.code\", { style: { color: \"#505050\" } });\n                        }\n                        console.log(res.data.materialAttr);\n                        console.log(res.data);\n                    } else {\n                        //console.log(res.msg);\n                    }\n                });\n            }\n        };\n\n        for (var i = 0; i < data.length; i++) {\n            _loop(i);\n        }\n    }, 1000);\n});","regionType":"DATAGRID","convertPdfOnLine":true,"modelCode":"WOM_1.0.0_produceTask_TaskProcess","rowspan":1,"complex":true,"autoAddRow":false,"showType":"DATAGRID","isgroup":false,"isCreateNew":false,"renderOver":"// 设置按钮都不可用\nsetBtnStyle(''btn-startProcess'', false);\nsetBtnStyle(''btn-endProcess'', false);\nsetBtnStyle(''btn-setUnit'', false);\nsetBtnStyle(''btn-otherActive'', false);\n\nlet dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988483'');\nlet processes = dataGrid.getDatagridData();\nfor (let process of processes) {\n    if (!process.processRunState) {\n        continue;\n    }\n    // 显示颜色\n    let color;\n    let runState = process.processRunState.id;\n    if (runState === ''WOM_runState/waitForRun'') {\n        // 待执行，灰色\n        color = ''#e8e8e8'';\n    } else if (runState === ''WOM_runState/runing'') {\n        // 执行中，绿色\n        color = ''#95de64'';\n    } else if (runState === ''WOM_runState/iskeep'') {\n        // 已暂停，黄色\n        color = ''#fff566'';\n    } else if (runState === ''WOM_runState/finished'') {\n        // 正常结束，蓝色\n        color = ''#69c0ff'';\n    } else {\n        color = ''white'';\n    }\n    // 设置背景颜色\n    dataGrid.setDatagridCellAttr(process.rowIndex, \"processRunState.value\", { style: { background: color } });\n}","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1576028988369_47","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1576028988483","hasFastQuery":false,"fields":[{"showTypeHasChanged":false,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_makeTaskViewdg1576028988483_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskProcess_name","nullable":true,"isTotal":false,"showFormatHasChanged":false,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","propertyCode":"WOM_1.0.0_produceTask_TaskProcess_name","regionType":"DATAGRID","layRec":"name","modelCode":"WOM_1.0.0_produceTask_TaskProcess","namekey":"WOM.produceTask.TaskProcess.name","isreadonly":true,"showType":"TEXTFIELD","isgroup":false,"key":"name","popView":false,"showFormat":"TEXT","cellCode":"cell_1576028988496_1","mneenable":false,"label":"工序名称","isHidden":false,"columnType":"TEXT","hide":false,"isrefselect":false,"pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrVmlld19zZWxmfA__","width":100,"textalign":"left","isCustom":false,"multable":false,"maxLength":255,"columnName":"NAME"},{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_makeTaskViewdg1576028988483_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskProcess_processRunState","nullable":true,"isTotal":false,"showFormatHasChanged":true,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"SYSTEMCODE","propertyCode":"WOM_1.0.0_produceTask_TaskProcess_processRunState","regionType":"DATAGRID","layRec":"processRunState","modelCode":"WOM_1.0.0_produceTask_TaskP