:"left","isCustom":false,"modelcode":"HierarchicalMod_1.0.0_factoryModel_FactoryModel","refCondition":"// 工单工序表格\nlet dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskEditdg1575440388973'');\n// 生产线组件\nlet lineComponent = ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.lineId.name'');\n// 所选工单工序\nlet taskProcess = dataGrid.getSelecteds()[0];\n// 配方工序id\nlet processId = taskProcess.formulaProcessId.id;\nlet lineId = lineComponent.getValue().length ? lineComponent.getValue()[0].id : -1;\nreturn \"processId=\" + processId + \"&lineId=\" + lineId;","multable":false,"maxLength":255,"columnName":"NAME"},{"showTypeHasChanged":false,"precisionHasChanged":true,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_makeTaskViewdg1576028988483_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskProcess_procSort","nullable":true,"isTotal":false,"showFormatHasChanged":false,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","propertyCode":"WOM_1.0.0_produceTask_TaskProcess_procSort","regionType":"DATAGRID","layRec":"procSort","modelCode":"WOM_1.0.0_produceTask_TaskProcess","namekey":"WOM.propertyshowName.randon1578288803288.flag","isreadonly":false,"showType":"TEXTFIELD","isgroup":false,"key":"procSort","popView":false,"showFormat":"TEXT","cellCode":"cell_1578288798543_9671","mneenable":false,"label":"报工顺序","isHidden":false,"columnType":"TEXT","hide":false,"isrefselect":false,"pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrVmlld19zZWxmfA__","width":100,"textalign":"left","isCustom":false,"multable":false,"maxLength":255,"columnName":"PROC_SORT"},{"showTypeHasChanged":false,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_makeTaskViewdg1576028988483_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskProcess_remark","nullable":true,"isTotal":false,"showFormatHasChanged":false,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"LONGTEXT","propertyCode":"WOM_1.0.0_produceTask_TaskProcess_remark","regionType":"DATAGRID","layRec":"remark","modelCode":"WOM_1.0.0_produceTask_TaskProcess","namekey":"WOM.produceTask.TaskProcess.remark","isreadonly":false,"showType":"TEXTFIELD","isgroup":false,"key":"remark","popView":false,"showFormat":"TEXT","cellCode":"cell_1576028988496_5","mneenable":false,"label":"备注","isHidden":false,"columnType":"LONGTEXT","hide":false,"isrefselect":false,"pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrVmlld19zZWxmfA__","width":100,"textalign":"left","isCustom":false,"multable":false,"columnName":"REMARK"}],"treePaging":false,"isNoCopy":false,"isCheckBox":false,"cannotAddNewRow":true,"acceptRevisions":false,"targetPropertyCode":"WOM_1.0.0_produceTask_TaskProcess_taskId","code":"WOM_1.0.0_produceTask_makeTaskViewdg1576028988483","idPrefix":"TaskProcess_dg1576028988483","hideRevision":false,"title":"WOM.dataGriddataGridName.randon1575440661677.flag","maxTableHeight":0,"getRevisions":false,"ptPageInit":"//$(\"#btn-otherActive\").hide();\n// 样式修改不可使用JQuery,需要使用平台提供的方法\nlet sdg = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988483'');\n// 开始样式\nsdg.setBtnImg(''btn-startProcess'', ''sup-btn-own-qiyong'');\n// 停止样式\nsdg.setBtnImg(''btn-endProcess'', ''sup-btn-own-ty'');\n\n// 工序列表\nlet processDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988483'');\n// 指令单\nlet task = ReactAPI.getFormData();\n// 指令单执行状态\nlet taskRunState = task.taskRunState.id;\n// 设置点击事件\nprocessDataGrid.setClickEvt((event, process) => {\n    let processRunState = process.processRunState.id;\n    // 开始工序按钮，情况：指令单在执行中，且工序在待执行状态\n    setBtnStyle(''btn-startProcess'', taskRunState === ''WOM_runState/runing'' && processRunState === ''WOM_runState/waitForRun'');\n\n    // 结束工序按钮, 情况：指令单在执行中，且工序在进行中状态\n    setBtnStyle(''btn-endProcess'', taskRunState === ''WOM_runState/runing'' && processRunState === ''WOM_runState/runing'');\n\n    // 设置工作单元按钮，情况：指令单在执行中，且工序在进行中状态\n    setBtnStyle(''btn-setUnit'', taskRunState === ''WOM_runState/runing'' && processRunState === ''WOM_runState/runing'');\n\n    // 机动执行按钮，情况：指令单在非待执行，且工序在非待执行中\n    setBtnStyle(''btn-otherActive'', taskRunState !== ''WOM_runState/waitForRun'' && processRunState !== ''WOM_runState/waitForRun'');\n\n    let activeDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988507'');\n    // 根据工单工序获取工单活动\n    activeDataGrid.refreshDataByRequst({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/taskActive/queryByProcess?processId=\" + process.id + \"&showBatch=false\",\n        param: {}\n    });\n    //判断物料属性是否为危化品\nsetTimeout(function(){\n    let data=ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskViewdg1576028988507\").getDatagridData();\n    console.log(data);\n    for(let i=0;i<data.length;i++){\n        if(data[i].materialId!=null){//如果物料编码字段不为空，则发送请求\n        ReactAPI.request({\n            type: \"get\",\n            url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttribute?materialCode=\"+data[i].materialId.id,\n            contentType: \"application/json;charset=UTF-8\",\n        }, function (res) {\n            if(res.code==200){\n                if(res.data.materialAttr==true){//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                    .APIs(\"WOM_1.0.0_produceTask_makeTaskViewdg1576028988507\")\n                    .setDatagridCellAttr(data[i].rowIndex, \"materialId.code\", { style: { color: \"#B30303\" } });\t\n                }\n                else{\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                    .APIs(\"WOM_1.0.0_produceTask_makeTaskViewdg1576028988507\")\n                    .setDatagridCellAttr(data[i].rowIndex.rowIndex, \"materialId.code\", { style: { color: \"#505050\" } });\n                }\n              console.log(res.data.materialAttr);\t\n              console.log(res.data);\n            }else{\t\n                //console.log(res.msg);\n            }\n        }\n        );\n    }\n    }\n}, 1000);\n});","colspan":1,"exportExcel":false,"showRevision":false,"colNum":8,"hideKey":"''id'',''version'',''processType.id'',''taskId.id'',''formulaId.id'',''equipmentId.id'',''formulaProcessId.id'',''id.id''","isreadonly":0,"officePrint":false,"canNotDeleteRow":true,"downloadDoc":true,"buttons":[{"isSignatureConfig":true,"funcbody":"function startProcessEvent(event) {\n    console.log(''%c startProcess'', ''color:#3AFF11;'');\n    let dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988483'');\n    let task = ReactAPI.getFormData();\n    // 获取选中行\n    let process = dataGrid.getSelecteds()[0];\n    // 开启遮罩\n    ReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing''));\n    // 开启工序\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/taskProcess/start/\" + process.id\n    },\n        res => {\n        // 关闭遮罩\n        ReactAPI.closeLoading();\n        if (res.dealSuccessFlag) {\n            // 刷新列表\n            dataGrid.refreshDataByRequst({\n                type: \"POST\",\n                url: \"/msService/WOM/produceTask/produceTask/data-dg1576028988483?datagridCode=WOM_1.0.0_produceTask_makeTaskViewdg1576028988483&id=\" + task.id,\n                param: {\n                    pageSize: 65535\n                }\n            });\n            // 清空工单活动表\n            ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988507'').deleteLine();\n        } else {\n            ReactAPI.showMessage(\"f\", res.errorMessage);\n        }\n    });\n}","funcname":"onclick=''startProcessEvent(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1576045667879_5394","isHide":false,"showname":"开始","pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX