                   }\n                                });\n                                // 清空工单活动表\n                                ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskViewdg1576028988507\").deleteLine();\n                            } else {\n                                ReactAPI.showMessage(\"f\", res.errorMessage);\n                            }\n                        });\n                    }\n                }, {\n                    operatetype: \"no\",\n                    text: \"否\",\n                    type: \"primary\",\n                    onClick: function onClick() {\n                        ReactAPI.closeConfirm();\n                    }\n                }]\n            });\n        } else {\n            // 结束工序\n            ReactAPI.request({\n                type: \"post\",\n                url: \"/msService/WOM/produceTask/taskProcess/end/\" + process.id\n            }, function (res) {\n                // 关闭遮罩\n                ReactAPI.closeLoading();\n                if (res.dealSuccessFlag) {\n                    // 刷新列表\n                    dataGrid.refreshDataByRequst({\n                        type: \"POST\",\n                        url: \"/msService/WOM/produceTask/produceTask/data-dg1576028988483?datagridCode=WOM_1.0.0_produceTask_makeTaskViewdg1576028988483&id=\" + task.id,\n                        param: {\n                            pageSize: 65535\n                        }\n                    });\n                    // 清空工单活动表\n                    ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskViewdg1576028988507\").deleteLine();\n                } else {\n                    ReactAPI.showMessage(\"f\", res.errorMessage);\n                }\n            });\n        }\n    });\n}","id":"endProcess","operatetype":"CUSTOM","isconfirm":false},{"isSignatureConfig":true,"funcbody":"function setUnitEvent(event) {\n    // 是否在打开''工序工作单元''编辑视图时执行onload事件里的查询\n    window.isActive = true;\n    \n    let dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988483'');\n    let task = ReactAPI.getFormData();\n    // 获取选中行\n    let process = dataGrid.getSelecteds()[0];\n    let powerCode = ReactAPI.getParamsInRequestUrl()[''__pc__''];\n    let dialogName = ''processUnitSet'';\n    // 打开工序编辑对话框\n    ReactAPI.createDialog(dialogName, {\n        title: ''工序工作单元'',\n        url: ''/msService/WOM/produceTask/taskProcess/processUnitEdit?id='' + process.id + ''&__pc__='' + powerCode,\n        isRef: false, // 是否开启参照\n        size: 1,\n        buttons: [\n            {\n                text: \"保存\",\n                type: \"primary\",\n                onClick: event => {\n                    // 提交当前iframe页面\n                    event.ReactAPI.submitFormData(\"save\", res => {\n                        if (res.success) { //保存成功时，关闭窗口\n                            ReactAPI.destroyDialog(dialogName);\n                            // 刷新列表\n                            dataGrid.refreshDataByRequst({\n                                type: \"POST\",\n                                url: \"/msService/WOM/produceTask/produceTask/data-dg1576028988483?datagridCode=WOM_1.0.0_produceTask_makeTaskViewdg1576028988483&id=\" + task.id,\n                                param: {\n                                    pageSize: 65535\n                                }\n                            });\n                            // 清空工单活动表\n                            ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988507'').deleteLine();\n                        }\n                    });\n                }\n            },\n            {\n                text: \"取消\",\n                onClick: event => {\n                    ReactAPI.destroyDialog(dialogName);\n                }\n            }\n        ]\n    });\n}","funcname":"onclick=''setUnitEvent(event)''","b