processRunState = selectedProcess.processRunState.id;\n    // 设置选中工序\n    processDataGrid.setSelecteds(selectedProcess.rowIndex + '''');\n\n    // 活动执行状态\n    let activeRunState = active.runState.id;\n\n    // 开始按钮，可用情况：指令单为执行中，且工序为待执行或执行中，且活动为待执行\n    setBtnStyle(''btn-startActive'',\n        taskRunState === ''WOM_runState/runing''\n        && (processRunState === ''WOM_runState/waitForRun'' || \n                processRunState === ''WOM_runState/runing'')\n        && (activeRunState === ''WOM_runState/waitForRun''));\n   /*\n    * 结束按钮，可用情况：\n    *  1. 指令单类型为 ''非检验'' : 指令单为执行中 && 工序为执行中 && 且活动为执行中   \n    *  2. 指令单类型为 ''检验''  : 指令单为执行中 && 工序为执行中 && 活动为执行中 && 活动未勾选''放行检''\n    */\n    let enable = (taskRunState === ''WOM_runState/runing''\n        && processRunState === ''WOM_runState/runing''\n        && activeRunState === ''WOM_runState/runing'');\n    if (active.activeType.id === ''RM_activeType/quality'') {\n\t\tenable = (enable && !active.isPassCheck);\n    }\n    setBtnStyle(''btn-endActive'', enable);\n\t\n   /*\n    * 提前放行按钮，可用情况：\n    *  1. 判断当前活动是否为检验活动   \n    *  2. 判断当前活动的放行检验、完工检验、是否提前放行的状态是否为true\n    */\n\tlet advanceReleaseFlag = (taskRunState === ''WOM_runState/runing'' \n\t&& processRunState === ''WOM_runState/runing''\n    && activeRunState === ''WOM_runState/runing'');\n\tif(active.activeType.id == ''RM_activeType/quality'') {\n\t\tadvanceReleaseFlag = advanceReleaseFlag && active.isPassCheck && active.isRelease;\n\t}\n\tsetBtnStyle(''btn-advanceRelease'', advanceReleaseFlag);\n\t\n});\n\n// 设置双击事件\nactiveDataGrid.setDbclickEvt((event, active) => {\n    console.log(''%c DbclickEvt'',''color:#3AFF11;'');\n    // 活动执行状态\n    let activeRunState = active.runState.id;\n\n    // 活动对应工序id\n    let processId = active.taskProcessId.id;\n    let processes = processDataGrid.getDatagridData();\n    // 对应选中工序行\n    let selectedProcess = processes.filter(process => process.id === processId)[0];\n    // 工序执行状态\n    let processRunState = selectedProcess.processRunState.id;\n\n    // 如果活动是待执行状态，或者(指令单为暂停中或工序为完成)且活动是执行中，无法打开报工界面\n    if (activeRunState === ''WOM_runState/waitForRun'' || ((taskRunState === ''WOM_runState/paused'' || processRunState === ''WOM_runState/finished'') && activeRunState === ''WOM_runState/runing'')) {\n        return;\n    }\n    let url;\n    switch (active.activeType.id) {\n        case \"RM_activeType/check\": // 检查\n            url = ''/msService/WOM/procReport/procReport/checkFeedBack'';\n            break;\n        case \"RM_activeType/putin\": // 人工投料\n            url = ''/msService/WOM/procReport/procReport/putInFeedBack'';\n            break;\n        case \"RM_activeType/pipePutin\": // 管道投料\n            url = ''/msService/WOM/procReport/procReport/putInFeedBack'';\n            break;\n        case \"RM_activeType/output\": // 人工产出\n            url = ''/msService/WOM/procReport/procReport/outputFeedBack'';\n            break;\n        case \"RM_activeType/pipeOutput\": // 管道产出\n            url = ''/msService/WOM/procReport/procReport/outputFeedBack'';\n            break;\n        case \"RM_activeType/batchPutin\": // 人工投配料\n            url = ''/msService/WOM/procReport/procReport/batchFeedBack'';\n            break;\n        case \"RM_activeType/pipeBatchPutin\": // 管道投配料\n            url = ''/msService/WOM/procReport/procReport/batchFeedBack'';\n            break;\n        default:\n            return;\n    }\n    // 获取工序报工id\n    ReactAPI.request(\n        {\n            type: \"get\",\n            url: \"/msService/WOM/procReport/procReport/by/active/\" + active.id\n        },\n        res => {\n            console.log(''%c 报工双击事件'',''color:red;'');\n            if (res.data.dealSuccessFlag) {\n                let powerCode = ReactAPI.getParamsInRequestUrl()[''__pc__''];\n                // 如果是执行中状态，则打开edit视图，否则打开view视图\n                url += activeRunState === ''WOM_runState/runing'' ? ''Edit'' : ''View'';\n                window.open(url + ''?id='' + res.data.procReportId + ''&__pc__='' + powerCode + ''&customConditionKey=operateType&operateType=routine'');\n            } else {\n                ReactAPI.showMessage(\"f\", res.data.errorMessage);\n            }\n        }\n    );\n});","colspan":1,"exportExcel":false,"showRevision":false,"colNum":8,"hideKey":"''id'',''version'',''formulaActiveId.id'',''taskId.id'',''checkStaffId.id'',''checkDepId.id'',''formulaId.id'',''applyCheckStaffId.id'',''taskProcessId.id'',''materialId.id'',''formulaProcessId.id'',''id.id'',''applyCheckDepId.id''","isreadonly":0,"officePrint":false,"canNotDeleteRow":true,"downloadDoc":true,"buttons":[{"isSignatureConfig":true,"funcbody":"function startActive(event) {\n    console.log(''startActive'');\n    var activeDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988507'');\n    var activeData = activeDataGrid.getSelecteds();\n    var activeId = activeData[0].id\n        var processDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988483'');\n    var processId = activeData[0].taskProcessId.id;\n    var formData = ReactAPI.getFormData();\n    var taskId = formData.id;\n    // 开启遮罩\n    ReactAPI.openLoading(ReactAPI.international.getText(''EditView.notice.processing''));\n    //根据活动获取工序，判断工序顺序，之后判断活动顺序,判断正确开始活动\n    $.ajax({\n        url: \"/msService/WOM/produceTask/produceTask/startActive\",\n        type: ''get'',\n        async: true,\n        data: {\n            activeId: activeId\n        },\n        success: function (res) {\n            // 关闭遮罩\n            ReactAPI.closeLoading();\n            if (res.code==200) {\n                let data = res.data;\n                if (data.success) {\n                    ReactAPI.showMessage(\"s\", \"活动已开始！\");\n                    // 根据工单工序获取工单活动\n                    activeDataGrid.refreshDataByRequst({\n                        type: \"post\",\n                        url: \"/msService/WOM/produceTask/taskActive/queryByProcess?processId=\" + processId + \"&showBatch=false\",\n                        param: {}\n                    })\n                    //刷新工序\n                    processDataGrid.refreshDataByRequst({\n                        type: \"post\",\n                        url: \"/msService/WOM/produceTask/produceTask/data-dg1576028988483?datagridCode=WOM_1.0.0_produceTask_makeTaskViewdg1576028988483&id=\" + taskId,\n                        param: {}\n                    });\n                    //选中工序行\n                    for (var i = 0; i < processDataGrid.getDatagridData().length; i++) {\n                        var process = processDataGrid.getDatagridData()[i].id;\n                        if (process == processId) {\n                            ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988483'').setSelecteds(\"\" + i);\n                        }\n                    }\n                    console.log(''Reflush'');\n                    //刷新父页面\n                    if (opener) {\n                        opener.ReactAPI.getComponentAPI(''ListView'').SearchList.submitEditDialogCallback()\n                    }\n                } else {\n                    ReactAPI.showMessage(\"f\", data.msg);\n                }\n            } else {\n                ReactAPI.showMessage(\"f\", res.msg);\n            }\n        }\n    });\n}","funcname":"onclick=''startActive(event)''","buttonstyle":"add","iscustomfunc":false,"useInMore":false,"isPublished":false,"ispermission":false,"cellCode":"cell_1576044608039_8093","isHide":false,"showname":"开始","pc":"__pc__=V09NXzEuMC4wX3Byb2R1Y2VUYXNrX21ha2VUYXNrVmlld19zZWxmfA__","regionType":"BUTTON","iscallback":false,"namekey":"WOM.buttonPropertyshowName.randon1576044613163.flag","funcbody_es5":"function startActive(event) {\n    console.log(''startActive'');\n    var activeDataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskViewdg1576028988507'');\n  