[0].finalInspection == true && selectedRow[0].activeBatchState != null && selectedRow[0].activeBatchState.dealType.id == \"BaseSet_dealType/adjust\") {\n                ReactAPI.showMessage(''w'', ReactAPI.international.getText(\"WOM.custom.random1619487476678\"));\n                return;\n            }\n\n            var formulaActiveId = selectedRow[0].formulaActiveId.id;\n            ReactAPI.request({\n                type: \"get\",\n                data: {},\n                url: \"/msService/RM/formula/processActive/findByFormulaActiveId/\" + formulaActiveId\n            }, function (res) {\n                var result = res.data.processActive;\n                if (result.isRelease == false) {\n                    ReactAPI.showMessage(''w'', ReactAPI.international.getText(\"WOM.custom.randon1596786078588\", selectedRow[0].name));\n                } else {\n                    var taskId = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskViewdg1576028988507\").getSelecteds()[0].taskId.id;\n                    var name = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskViewdg1576028988507\").getSelecteds()[0].name;\n                    var resultFlag = null;\n                    ReactAPI.request({\n                        type: \"get\",\n                        data: {\n                            taskId: taskId,\n                            name: name\n                        },\n                        url: \"/msService/WOM/produceTask/produceTask/getFlagByNumAndName\"\n                    }, function (res1) {\n                        if (res1.code == 200) {\n                            debugger;\n                            resultFlag = res1.data.result;\n                            if (!resultFlag) {\n                                ReactAPI.showMessage(''w'', ReactAPI.international.getText(\"WOM.custom.randon1597655885101\", selectedRow[0].name));\n                            } else {\n\n          