// 正常结束，蓝色\n            color = ''#69c0ff'';\n        } else {\n            color = ''white'';\n        }\n        // 设置背景颜色\n        activeDataGrid.setDatagridCellAttr(active.rowIndex, \"runState.value\", {\n            style: {\n                background: color\n            }\n        });\n    }\n} catch (err) {\n    _didIteratorError = true;\n    _iteratorError = err;\n} finally {\n    try {\n        if (!_iteratorNormalCompletion && _iterator.return) {\n            _iterator.return();\n        }\n    } finally {\n        if (_didIteratorError) {\n            throw _iteratorError;\n        }\n    }\n}","copyRow":false,"queryUrl":null,"saveTemplate":false,"pendingDeal":false,"isTreeView":false,"openEmptyDoc":true,"multable":false}],"regionType":"DATAGRID","colwidth":"13,20,13,20,13,20","cssstyle":null,"customSection":null,"colNum":6,"name":null,"sectionCode":null,"refcol":"<tr style=''border:none;height:0px; ''><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td><td style=''height:0px;border:none;width:13%''></td><td style=''height:0px;border:none;width:20%''></td></tr>","type":"layoutSection"}],"isrightbottomfixed":false,"layoutContent":"datagrid","type":"layout","ranksType":"panel","isShow":true,"isreadonlyBak":0,"parlayoutname":"tabs-3","ratio_h":50,"layoutmethod":"container","ptRealTimeLoad":0,"isreadonly":0,"layno":3,"layoutname":"column-9","islefttopfixed":false,"nums":1}],"tabViewIndex":0,"isborder":1,"isrightbottomfixed":false,"ranksType":"panel","isShow":true,"isreadonlyBak":0,"parlayoutname":"tabs-1","ptRealTimeLoad":0,"layoutmethod":"column","namekey":"WOM.tabnamenew2.randon1575439929121.flag","name":"工序活动","isreadonly":0,"layno":2,"id":"tabs-3","tabCode":"tabs-3","layoutname":"tabs-3","islefttopfixed":false,"nums":3}],"isrightbottomfixed":false,"type":"layout","isreadonlyBak":0,"ptRealTimeLoad":1,"