"&entityCode=WOM_1.0.0_putInMaterial\"\n        + \"&iscrosscompany=false\"\n        + \"&openType=frame\"\n        + \"&iscallback=false\"\n        + \"&id=\" + encodeURIComponent(recordId);\n    window.open(target, \"_blank\");\n    return true;\n}","isdbcustom":true,"modelCode":"WOM_1.0.0_putInMaterial_PutMateiDetail","downloadXls":"/msService/WOM/putInMaterial/putMateiDetail/downloadXls","selectFirstRow":false,"renderOver":"//判断是否为危化品    \nsetTimeout(function () {\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_putInMaterial_putInDetailList_putMateiDetail_sdg\").getDatagridData();\n    let materialId = [];\n    for (let i = 0; i < data.length; i++) {\n        if (data[i].materialId != null && data[i].materialId.id != null) {\n            materialId.push({ \"materialId\": data[i].materialId.id });\n        }\n        else\n            materialId.push({ \"materialId\": -1 });\n    }\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if (res.code = 200) {\n            for (let i = 0; i < data.length; i++) {//遍历\n                if (res.data[i] != null && res.data[i] == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_putInMaterial_putInDetailList_putMateiDetail_sdg\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" } });\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_putInMaterial_putInDetailList_putMateiDetail_sdg\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" } });\n                }\n            }\n        }\n    }\n    );\n}, 1000);","buttons":[{"id":"viewDetail","showname":"查看详情","name":"查看详情","namekey":"查看详情","i18nKey":"查看详情","buttonstyle":"view","operatetype":"CUSTOM","operateType":"CUSTOM","isHide":false,"ispermission":false,"isPublished":true,"iscallback":false,"iscustomfunc":false,"useInMore":false,"isconfirm":false,"isSignatureConfig":true,"regionType":"BUTTON","cellCode":"cell_adp_WOM_1_0_0_putInMaterial_putInDetailList_viewDetail_view","buttonoperationcode":"WOM_1.0.0_putInMaterial_putInDetailList_viewDetail_view","CODE":"WOM_1.0.0_putInMaterial_putInDetailList_viewDetail_view","NAME":"查看详情","ICONCLS":"cui-btn-view","USEINMORE":false,"SEPARATENUM":"0","ecEnv":"product","modelCode":"WOM_1.0.0_putInMaterial_PutMateiDetail","viewselect":{"title":"WOM.viewtitle.randon1617707202267","code":"WOM_1.0.0_putInMaterial_putInDetailView","name":"putInDetailView","openType":"dialog","url":"/msService/WOM/putInMaterial/putMateiDetail/putInDetailView","iscrosscompany":"false","mneType":"other"},"funcname":"onclick=''viewWomPutInDetailList()''","onclick":"viewWomPutInDetailList()","ONCLICK":"viewWomPutInDetailList()","funcbody":"function viewWomPutInDetailList() {\n    var gridFactory = ReactAPI.getComponentAPI(\"SupDataGrid\");\n    var grid = gridFactory && gridFactory.APIs(\"WOM_1.0.0_putInMaterial_putInDetailList_putMateiDetail_sdg\");\n    var selected = grid && grid.getSelecteds ? grid.getSelecteds() : [];\n    if (!selected || !selected.length) {\n        ReactAPI.showMessage(\"w\", \"请选择一条生产用料明细\");\n        return false;\n    }\n    var row = selected[0];\n    function valueAtPath(source, path) {\n        if (!source) { return null; }\n        if (Object.prototype.hasOwnProperty.call(source, path)) {\n            return source[path];\n        }\n        var value = source;\n        var parts = path.split(\".\");\n        for (var index = 0; index < parts.length; index += 1) {\n            if (value === null || value === undefined) { return null; }\n            value = value[parts[index]];\n        }\n        if (value && typeof value === \"object\" && value.id !== undefined) {\n            return value.id;\n        }\n        return value;\n    }\n    var recordId = valueAtPath(row, \"id\");\n    if (!recordId) {\n        ReactAPI.showMessage(\"w\", \"请选择一条生产用料明细\");\n        return false;\n    }\n    var target = \"/msService/WOM/putInMaterial/putMateiDetail/putInDetailView\"\n        + \"?viewCode=WOM_1.0.0_putInMaterial_putInDetailList\"\n        + \"&entityCode=WOM_1.0.0_putInMaterial\"\n        + \"&iscrosscompany=false\"\n        + \"&openType=frame\"\n        + \"&iscallback=false\"\n        + \"&id=\" + encodeURIComponent(recordId);\n    window.open(target, \"_blank\");\n    return true;\n}","funcbody_es5":"function viewWomPutInDetailList() {\n    var gridFactory = ReactAPI.getComponentAPI(\"SupDataGrid\");\n    var grid = gridFactory && gridFactory.APIs(\"WOM_1.0.0_putInMaterial_putInDetailList_putMateiDetail_sdg\");\n    var selected = grid && grid.getSelecteds ? grid.getSelecteds() : [];\n    if (!selected || !selected.length) {\n        ReactAPI.showMessage(\"w\", \"请选择一条生产用料明细\");\n        return false;\n    }\n    var row = selected[0];\n    function valueAtPath(source, path) {\n        if (!source) { return null; }\n        if (Object.prototype.hasOwnProperty.call(source, path)) {\n            return source[path];\n        }\n        var value = source;\n        var parts = path.split(\".\");\n        for (var index = 0; index < parts.length; index += 1) {\n            if (value === null || value === undefined) { return null; }\n            value = value[parts[index]];\n        }\n        if (value && typeof value === \"object\" && value.id !== undefined) {\n            return value.id;\n        }\n        return value;\n    }\n    var recordId = valueAtPath(row, \"id\");\n    if (!recordId) {\n        ReactAPI.showMessage(\"w\", \"请选择一条生产用料明细\");\n        return false;\n    }\n    var t