;\n                }\n                else if (res.data[i] != null && res.data[i] == false) {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590\")\n                        .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" }, readonly: true });\n                }\n            }\n        }\n    }\n    );\n}","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1597224490792_9507","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1597224100590","hasFastQuery":false,"fields":[{"callbackbody":"function callbackPosition(obj) {\n    //发出一个请求，根据物料编码查找物料属性，返回物料属性的值，如果物料属性的值为危化品，则将单元格的物料编码字段设置为红色，其他情况不做处理\n    let data = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590\");\n    let datarows = data.getSelecteds();\n    let materialCode;\n    if (datarows.length != 0 && datarows[0].materialId != null) {\n        materialCode = datarows[0].materialId.id;\n        ReactAPI.request({\n            type: \"get\",\n            url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttribute?materialCode=\" + materialCode,\n            contentType: \"application/json;charset=UTF-8\",\n        }, function (res) {\n            if (res.success) {\n                if (res.data.materialAttr == true) {//如果是危化品则为红色\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg1597224100590\")\n                        .setDatagridCellAttr(datarows[0].rowIndex, \"materialId.code\", { style: { color: \"#B30303\" } });\n                }\n                else {\n                    ReactAPI.getComponentAPI(\"SupDataGrid\")\n                        .APIs(\"WOM_1.0.0_rejectMaterilal_materiaRejectEditdg15